
@import '../styles/variables.scss';

.preview,
.preview__inner-1 {
  position: absolute;
  width: 100%;
  height: 100%;
}

.preview__inner-1 {
  overflow: auto;
}

.preview__inner-2 {
  margin: 0;
}

.preview__inner-2 > :first-child > :first-child {
  margin-top: 0;
}

$corner-size: 110px;

.preview__corner {
  position: absolute;
  top: 0;
  right: 0;

  &::before {
    content: '';
    position: absolute;
    right: 0;
    border-top: $corner-size solid rgb(0 0 0 / 7.5%);
    border-left: $corner-size solid transparent;
    pointer-events: none;

    .app--dark & {
      border-top-color: rgb(255 255 255 / 7.5%);
    }
  }
}

.preview__button {
  position: absolute;
  top: 15px;
  right: 15px;
  width: 40px;
  height: 40px;
  padding: 5px;
  color: rgb(0 0 0 / 25%);

  .app--dark & {
    color: rgb(255 255 255 / 25%);
  }

  &:active,
  &:focus,
  &:hover {
    color: rgb(0 0 0 / 33%);
    background-color: transparent;

    .app--dark & {
      color: rgb(255 255 255 / 33%);
    }
  }
}
