
@import '../styles/variables.scss';

.button-bar {
  position: absolute;
  width: 100%;
  height: 100%;
}

.button-bar__inner {
  position: absolute;
}

.button-bar__inner--bottom {
  bottom: 0;
}

.button-bar__button {
  color: rgb(0 0 0 / 20%);
  display: block;
  width: 26px;
  height: 26px;
  padding: 2px;
  margin: 3px 0;

  .app--dark & {
    color: rgb(255 255 255 / 15%);
  }

  &:active,
  &:focus,
  &:hover {
    color: rgb(0 0 0 / 20%);

    .app--dark & {
      color: rgb(255 255 255 / 15%);
      background-color: $navbar-hover-background;
    }
  }
}

.button-bar__button--on {
  color: rgb(0 0 0 / 40%);

  .app--dark & {
    color: rgb(255 255 255 / 40%);
  }

  &:active,
  &:focus,
  &:hover {
    color: rgb(0 0 0 / 40%);

    .app--dark & {
      color: rgb(255 255 255 / 40%);
    }
  }
}
