
.stat-panel {
  position: absolute;
  width: 100%;
  height: 100%;
  color: #fff;
  font-size: 12px;
}

.stat-panel__block {
  margin: 0 10px;
}

.stat-panel__block--left {
  float: left;
}

.stat-panel__block--right {
  float: right;
}

.stat-panel__value {
  font-weight: 600;
  margin-left: 5px;
}

.stat-panel__save-status {
  display: inline-block;
  margin-left: 14px;
}

.stat-panel__save-status--error {
  color: #ffb3b3;
}
