
@import '../styles/variables.scss';

.find-replace {
  padding: 0 35px 0 25px;
}

.find-replace__row {
  margin: 10px 0;
}

.find-replace__button {
  font-size: 15px;
  padding: 0 8px;
  line-height: 28px;
  height: 28px;
}

.find-replace__button--find-option {
  padding: 0;
  width: 28px;
  font-weight: 600;
  letter-spacing: -0.025em;
  color: rgb(0 0 0 / 25%);
  text-transform: none;

  &:active,
  &:focus,
  &:hover {
    color: rgb(0 0 0 / 25%);
  }
}

.find-replace__button--on {
  color: rgb(0 0 0 / 67%);

  &:active,
  &:focus,
  &:hover {
    color: rgb(0 0 0 / 67%);
  }
}

.find-replace__text-input {
  border: 1px solid transparent;
  padding: 2px 5px;
  height: 32px;

  &:focus {
    border-color: $link-color;
  }
}

.find-replace__close-button {
  position: absolute;
  top: 5px;
  right: 5px;
  width: 25px;
  height: 25px;
  padding: 2px;
  color: rgb(0 0 0 / 50%);

  &:active,
  &:focus,
  &:hover {
    color: rgb(0 0 0 / 75%);
  }
}

.find-replace__find-stats {
  text-align: right;
  font-size: 0.75em;
  opacity: 0.6;
}

.find-replace-highlighting {
  background-color: $highlighting-color;
  color: $editor-color-light !important;
}

.find-replace-selection {
  background-color: $selection-highlighting-color;
}
